"use client";

import Link from "next/link";
import {
  BookOpen,
  FileText,
  LayoutDashboard,
  Menu,
  User,
  X,
} from "lucide-react";
import { useState } from "react";
import { usePathname } from "next/navigation";

import { Sheet, SheetContent, SheetTrigger } from "@/components/ui/sheet";
import { ThemeToggle } from "@/components/theme/theme-toggle";
import { cn } from "@/lib/utils";

const links = [
  ["Overview", "/dashboard", LayoutDashboard],
  ["Mock Exams", "/dashboard/mock-exams", FileText],
  ["Materials", "/dashboard/materials", BookOpen],
  ["Profile", "/dashboard/profile", User],
] as const;

export function DashboardSidebar() {
  const pathname = usePathname();
  const [open, setOpen] = useState(false);

  return (
    <Sheet open={open} onOpenChange={setOpen}>
      <>
        <div className="sticky top-0 z-40 flex h-14 items-center justify-between bg-primary px-4 text-cream lg:hidden">
          <Link href="/dashboard" className="font-heading text-base font-bold">
            BJS Prep
          </Link>
          <SheetTrigger
            type="button"
            aria-label={open ? "Close dashboard menu" : "Open dashboard menu"}
            aria-controls="dashboard-mobile-navigation"
            className="
              flex min-h-10 min-w-10 items-center justify-center rounded-md
              p-2 text-cream hover:bg-cream/10
            "
          >
            {open ? <X size={21} /> : <Menu size={21} />}
          </SheetTrigger>
        </div>

        <aside
          className="
            fixed inset-y-0 left-0 z-30 hidden h-screen w-64 bg-primary
            text-cream lg:block
          "
        >
          <SidebarLinks
            pathname={pathname}
            onNavigate={() => undefined}
          />
        </aside>

        <SheetContent
          id="dashboard-mobile-navigation"
          side="left"
          aria-label="Dashboard navigation"
          className="w-[280px] p-0 sm:w-[320px]"
        >
          <SidebarLinks
            pathname={pathname}
            onNavigate={() => setOpen(false)}
            mobile
          />
        </SheetContent>
      </>
    </Sheet>
  );
}

function SidebarLinks({
  pathname,
  onNavigate,
  mobile = false,
}: {
  pathname: string;
  onNavigate: () => void;
  mobile?: boolean;
}) {
  return (
    <div className="flex h-full min-h-0 flex-col px-4 py-6">
      <div className="flex items-center justify-between">
        <Link
          href="/dashboard"
          onClick={onNavigate}
          className={
            mobile
              ? "pr-12 font-heading text-lg font-bold"
              : "font-heading text-lg font-bold"
          }
        >
          BJS Prep
        </Link>
      </div>
      <nav className="mt-8 min-h-0 flex-1 space-y-1 overflow-y-auto pb-4">
        {links.map(([label, href, Icon]) => {
          const active = href === "/dashboard"
            ? pathname === href
            : pathname.startsWith(href);

          return (
            <Link
              key={href}
              href={href}
              onClick={onNavigate}
              className={cn(
                "relative flex min-h-11 items-center gap-3 rounded-md px-3 py-2 text-sm",
                "transition-colors focus-visible:outline-none focus-visible:ring-2",
                "focus-visible:ring-accent focus-visible:ring-offset-2",
                "focus-visible:ring-offset-primary hover:bg-cream/10 hover:text-cream",
                active ? "bg-cream/10 font-medium text-cream" : "text-cream/80",
              )}
            >
              {active ? (
                <span className="absolute inset-y-1 left-0 w-1 rounded-r bg-accent" />
              ) : null}
              <Icon size={18} />
              {label}
            </Link>
          );
        })}
      </nav>
      <div className="mt-auto shrink-0 border-t border-cream/15 pt-4">
        <p className="px-3 pb-1 text-xs text-cream/70">Theme</p>
        <ThemeToggle />
      </div>
    </div>
  );
}
